package it.motolink.app

import android.content.Context
import android.os.Build
import java.util.Locale

/**
 * V1.7: system-locale UI layer.
 *
 * MotoLink keeps technical logs stable for support, while user-facing strings are rendered
 * according to the phone language. Italian is preserved, English is the fallback for every
 * unsupported locale, and dedicated Russian / Simplified Chinese packs are provided.
 */
object MotoLinkLocale {
    private fun language(): String {
        val locale = if (Build.VERSION.SDK_INT >= 24) {
            android.os.LocaleList.getDefault().get(0)
        } else {
            @Suppress("DEPRECATION")
            Locale.getDefault()
        }
        return locale.language.lowercase(Locale.ROOT)
    }

    fun t(context: Context, raw: String): String {
        if (raw.isBlank()) return raw
        val lang = language()
        if (lang == "it") return raw
        val key = raw.trim()
        val exact = when (lang) {
            "ru" -> RU[key]
            "zh" -> ZH[key]
            else -> EN[key]
        }
        if (exact != null) return preserveOuterWhitespace(raw, key, exact)
        return dynamic(raw, lang)
    }

    private fun preserveOuterWhitespace(raw: String, key: String, translated: String): String {
        val prefix = raw.substringBefore(key)
        val suffix = raw.substringAfter(key, "")
        return prefix + translated + suffix
    }

    private fun dynamic(raw: String, lang: String): String {
        val tr = when (lang) {
            "ru" -> ::ruDynamic
            "zh" -> ::zhDynamic
            else -> ::enDynamic
        }
        return tr(raw)
    }

    private fun enDynamic(s: String): String = when {
        s.startsWith("Profilo moto ") -> "Motorcycle profile " + s.removePrefix("Profilo moto ")
        s.startsWith("Opzioni profilo ") -> "Profile options " + s.removePrefix("Opzioni profilo ")
        s.startsWith("Modifica app preferita ") -> "Edit favorite app " + s.removePrefix("Modifica app preferita ")
        s.startsWith("Cambia ") -> "Change " + s.removePrefix("Cambia ")
        s.startsWith("Rimuovi ") -> "Remove " + s.removePrefix("Rimuovi ")
        s.startsWith("Stato: ") -> "Status: " + s.removePrefix("Stato: ")
        s.startsWith("Collegato a:") -> "Connected to:" + s.removePrefix("Collegato a:")
        Regex("""^\d+ / 3 salvati$""").matches(s) -> s.replace("salvati", "saved")
        else -> EN_FALLBACK[s] ?: s
    }

    private fun ruDynamic(s: String): String = when {
        s.startsWith("Profilo moto ") -> "Профиль мотоцикла " + s.removePrefix("Profilo moto ")
        s.startsWith("Opzioni profilo ") -> "Параметры профиля " + s.removePrefix("Opzioni profilo ")
        s.startsWith("Modifica app preferita ") -> "Изменить избранное приложение " + s.removePrefix("Modifica app preferita ")
        s.startsWith("Cambia ") -> "Изменить " + s.removePrefix("Cambia ")
        s.startsWith("Rimuovi ") -> "Удалить " + s.removePrefix("Rimuovi ")
        s.startsWith("Stato: ") -> "Статус: " + s.removePrefix("Stato: ")
        s.startsWith("Collegato a:") -> "Подключено к:" + s.removePrefix("Collegato a:")
        Regex("""^\d+ / 3 salvati$""").matches(s) -> s.replace("salvati", "сохранено")
        else -> RU_FALLBACK[s] ?: EN[s] ?: EN_FALLBACK[s] ?: s
    }

    private fun zhDynamic(s: String): String = when {
        s.startsWith("Profilo moto ") -> "摩托车配置 " + s.removePrefix("Profilo moto ")
        s.startsWith("Opzioni profilo ") -> "配置选项 " + s.removePrefix("Opzioni profilo ")
        s.startsWith("Modifica app preferita ") -> "编辑常用应用 " + s.removePrefix("Modifica app preferita ")
        s.startsWith("Cambia ") -> "更改 " + s.removePrefix("Cambia ")
        s.startsWith("Rimuovi ") -> "移除 " + s.removePrefix("Rimuovi ")
        s.startsWith("Stato: ") -> "状态：" + s.removePrefix("Stato: ")
        s.startsWith("Collegato a:") -> "已连接：" + s.removePrefix("Collegato a:")
        Regex("""^\d+ / 3 salvati$""").matches(s) -> s.replace("salvati", "已保存")
        else -> ZH_FALLBACK[s] ?: EN[s] ?: EN_FALLBACK[s] ?: s
    }

